<?php
require_once __DIR__ . '/../includes/auth.php'; require_login(); $active_menu='reports';$rows=all_rows("SELECT a.appointment_id,a.appointment_date,a.service_price,CONCAT(c.first_name,' ',c.last_name) customer_name,c.phone,s.service_name,COALESCE(p.amount,0) amount_received,COALESCE(p.payment_status,'Unpaid') payment_status FROM appointments a JOIN customers c ON c.customer_id=a.customer_id JOIN services s ON s.service_id=a.service_id LEFT JOIN payments p ON p.appointment_id=a.appointment_id WHERE a.status <> 'Cancelled' AND (p.payment_id IS NULL OR p.payment_status IN ('Unpaid','Partially Paid')) ORDER BY a.appointment_date ASC");$page_title='Outstanding Payments Report';require __DIR__.'/../includes/header.php';
?>
<h2 class="print-heading">Outstanding Payments Report</h2><?php require __DIR__.'/../includes/report_nav.php';?><div class="card shadow-sm table-card"><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Appointment</th><th>Customer</th><th>Contact</th><th>Service</th><th>Charge</th><th>Received</th><th>Balance</th><th>Status</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="8" class="text-center py-4 text-secondary">There are no outstanding payments.</td></tr><?php endif;?><?php foreach($rows as $row):?><tr><td>#<?= (int)$row['appointment_id']?> · <?=e($row['appointment_date'])?></td><td><?=e($row['customer_name'])?></td><td><?=e($row['phone'])?></td><td><?=e($row['service_name'])?></td><td><?=money($row['service_price'])?></td><td><?=money($row['amount_received'])?></td><td class="fw-bold text-danger"><?=money((float)$row['service_price']-(float)$row['amount_received'])?></td><td><?=status_badge($row['payment_status'])?></td></tr><?php endforeach;?></tbody></table></div></div><?php require __DIR__.'/../includes/footer.php';
